import React from "react";
import { TouchableOpacity, Image } from "react-native";
import { useStore } from "../../store/Store";
import style from "./Buttons.styles";
import Logger from "../../utils/Logger";
import { ICONS } from "../../icons";
import { color } from "../../theme/color";
import { sharedObject } from "../../utils/common";
import { TOGGLE_END_CALL_DIALOG } from "../../store/ActionType";
const TAG = "EndCallButton";

export function EndCallButton() {
  const { jitsiManager, globalRef, nativeManager, dispatch, users } = useStore();
  const onHangUpCalled = () => {
    if (sharedObject.isPresenter === true && users.length > 1) {
      dispatch({
        type: TOGGLE_END_CALL_DIALOG,
        payload: true,
      });
      return;
    }
    try {
      Logger.d(TAG, "[onHangUpCalled]");
      globalRef.current.callEnded = true;
      if (nativeManager.current?.onCallEndButtonPressed)
        nativeManager.current.onCallEndButtonPressed();
    } catch (error) {
      Logger.d(TAG, "[onHangUpCalled]", error);
    }

    try {
      jitsiManager.current.leave();
    } catch (error) {
      Logger.d(TAG, "[onHangUpCalled]", error);
    }
  };
  return (
    <TouchableOpacity
      testID='cc-end-call'
      onPress={onHangUpCalled}
      style={[style.buttonContainer, { backgroundColor: color.redLight }]}
    >
      <Image style={style.buttonIcon} source={ICONS.END_CALL} />
    </TouchableOpacity>
  );
}
