import { Component } from "react";
import Logger from "../Logger";
import { Context } from "../../store/Store";
import { IContext } from "src/store/Context.types";

const TAG = "CallingAnalytics";
export default class Analytics extends Component {
  static contextType = Context;
  interval: NodeJS.Timer | null = null;
  appId: string | undefined = undefined;
  isAudioOnly: boolean | undefined = undefined;
  user: any = null;
  analyticsSettings: any;
  sessionId: any;
  constructor(props: any) {
    super(props);
  }

  componentDidMount() {
    this.appId = (this.context as IContext)?.settings.appId;
    this.isAudioOnly = (this.context as IContext)?.settings.isAudioOnly;
    this.analyticsSettings = (this.context as IContext)?.settings.analyticsSettings;
    this.sessionId = (this.context as IContext)?.settings.sessionId;
    this.user = (this.context as IContext)?.users[0];
    this.interval = setInterval(() => {
      this.ping();
    }, 60000);
  }

  componentWillUnmount() {
    // clearInterval(interval);
  }

  stopPing = () => {
    console.log("ping stopped");
    if (this.interval) {
      clearInterval(this.interval);
    }
  };

  getAnalyticsUrl() {
    const url = `https://${this.analyticsSettings.ANALYTICS_HOST}/${this.analyticsSettings.ANALYTICS_VERSION}/calls/ping`;
    return url;
  }

  async ping() {
    console.log("ping called", this.user);
    if ((this.context as IContext)?.globalRef?.current?.callEnded === true) {
      this.stopPing();
      return;
    }
    if (!this.appId || !this.user.jwt) {
      return;
    }
    const myHeaders = new Headers();
    myHeaders.append("appId", this.appId);
    myHeaders.append("authorization", "Beare " + this.user.jwt);
    myHeaders.append("Content-Type", "application/json");
    Logger.d(TAG, "Ping Headers => ", myHeaders);
    const data = {
      uts: Date.now(),
      wsId: this.user.resource,
      type: this.isAudioOnly ? "audio" : "video",
      sessionId: this.sessionId,
      isRecording: false,
    };
    const raw = JSON.stringify(data);
    Logger.d(TAG, "Ping data = ", data);
    const requestOptions: RequestInit = {
      method: "POST",
      headers: myHeaders,
      body: raw,
      redirect: "follow",
    };
    fetch(this.getAnalyticsUrl(), requestOptions)
      .then((response) => response.json())
      .then((result) => Logger.d(TAG, "Ping result => ", result))
      .catch((error) => Logger.e(TAG, "Ping error =>", error));
  }

  render() {
    return null;
  }
}

Analytics.contextType = Context;
