import React from "react";
import { EmitterSubscription, NativeEventEmitter, Platform } from "react-native";
import { IAudioMode } from "../store/GlobalState.types";
import { AUDIO_CALL_PREFERENCES, VIDEO_CALL_PREFERENCES } from "../utils/Constants";
import { SET_AUDIO_MODES, SET_SELECTED_AUDIO_MODE } from "../store/ActionType";
import { IContext } from "../store/Context.types";
import { Context } from "../store/Store";
import { IUser } from "../Types/Users";
import { debounce, removeTracksFromUserList, removeTracksFromUserObject } from "../utils/helper";
import Logger from "../utils/Logger";
import AudioMode from "./AudioMode";
import CometChatRTC from "./CometChatRTC";
import { globalSharedObject } from "../utils/common";
const TAG = "NativeManager";

export class NativeManager extends React.Component<any, any> {
  static contextType = Context;
  // declare context: React.ContextType<typeof Context>;
  eventEmitter: NativeEventEmitter;
  AudioModeEventEmitter: NativeEventEmitter;
  // list of listeners
  endCall: EmitterSubscription | undefined;
  cameraAvailability: EmitterSubscription | undefined;
  switchCameraSource: EmitterSubscription | undefined;
  muteAudio: EmitterSubscription | undefined;
  unMuteAudio: EmitterSubscription | undefined;
  pauseVideo: EmitterSubscription | undefined;
  unPauseVideo: EmitterSubscription | undefined;
  changeAudiModeToSpeaker: EmitterSubscription | undefined;
  changeAudiModeToEarpiece: EmitterSubscription | undefined;
  unmountComponent: EmitterSubscription | undefined;
  remountComponent: EmitterSubscription | undefined;
  enterPipMode: EmitterSubscription | undefined;
  exitPipMode: EmitterSubscription | undefined;
  switchToVideoCall: EmitterSubscription | undefined;
  startCallRecording: EmitterSubscription | undefined;
  stopCallRecording: EmitterSubscription | undefined;
  orientationChanged: EmitterSubscription | undefined;
  settings: any;
  isAudioDevicesInitialized = false;
  unsubscribeAudioModeEventEmitter: any;
  unsubscribeAudioModeEventEmitterCustom: any;
  audioDevices: any[];
  userList: any = [];
  previousAudioModeListToComarpe: any[] = [];
  audioModeEventTimer: any = null;

  constructor(props: any) {
    super(props);
    this.settings = props;
    this.audioDevices = [];
    if (CometChatRTC) this.eventEmitter = new NativeEventEmitter(CometChatRTC);
    this.AudioModeEventEmitter = new NativeEventEmitter(AudioMode);
    this.unsubscribeAudioModeEventEmitter = null;
    this.unsubscribeAudioModeEventEmitterCustom = null;
  }
  componentDidMount() {
    const { settings }: any = this.context;
    this.settings = settings;
    if (CometChatRTC) this.addListeners();
    if (AudioMode) {
      this.addAudioDeviceListener();
      if (Platform.OS === "android") AudioMode.getAllDevices();
    }

    if (Platform.OS === "android") {
      if (settings.defaultAudioMode) {
        AudioMode.setMode(AudioMode.VIDEO_CALL);
      } else {
        if (settings.isAudioOnly) {
          AudioMode.setMode(AudioMode.AUDIO_CALL);
        } else {
          AudioMode.setMode(AudioMode.VIDEO_CALL);
        }
      }
    } else if (Platform.OS === "ios") {
      AudioMode.updateDeviceList();
    }
  }

  getAudioModes = () => {
    return new Promise((resolve, reject) => {
      try {
        const { globalState }: any = this.context;
        resolve({ modes: globalState.audioModes });
      } catch (error) {
        reject(error);
      }
    });
  };

  resetAudioDeviceForVideoCall = () => {
    const { globalState }: any = this.context;
    for (let i = 0; i < VIDEO_CALL_PREFERENCES.length; i++) {
      const device = globalState.audioModes.find((item) =>
        item.type.toLowerCase().includes(VIDEO_CALL_PREFERENCES[i].toLowerCase())
      );
      if (device) {
        AudioMode.setAudioDevice(device?.uid || device.type);
        break;
      }
    }
  };

  setAudioMode = (mode) => {
    const { globalState }: any = this.context;
    const device = globalState.audioModes.find((item) =>
      item.type.toLowerCase().includes(mode.toLowerCase())
    );
    if (device) {
      AudioMode.setAudioDevice(device?.uid || device.type);
    }
  };

  setAudioDevices(allDevices: IAudioMode[]) {
    if (this.settings.defaultAudioMode) {
      const device = allDevices.find((item) => {
        return item.type.toLowerCase().includes(this.settings.defaultAudioMode.toLowerCase());
      });
      if (device) AudioMode.setAudioDevice(device?.uid || device?.type);
      else {
        if (this.settings.isAudioOnly) {
          for (let i = 0; i < AUDIO_CALL_PREFERENCES.length; i++) {
            const device = allDevices.find((item) =>
              item.type.toLowerCase().includes(AUDIO_CALL_PREFERENCES[i].toLowerCase())
            );
            if (device) {
              AudioMode.setAudioDevice(device?.uid || device.type);
              break;
            }
          }
        } else {
          for (let i = 0; i < VIDEO_CALL_PREFERENCES.length; i++) {
            const device = allDevices.find((item) =>
              item.type.toLowerCase().includes(VIDEO_CALL_PREFERENCES[i].toLowerCase())
            );
            if (device) {
              AudioMode.setAudioDevice(device?.uid || device.type);
              break;
            }
          }
        }
      }
    } else {
      if (this.settings.isAudioOnly) {
        for (let i = 0; i < AUDIO_CALL_PREFERENCES.length; i++) {
          const device = allDevices.find((item) =>
            item.type.toLowerCase().includes(AUDIO_CALL_PREFERENCES[i].toLowerCase())
          );
          if (device) {
            AudioMode.setAudioDevice(device?.uid || device.type);
            break;
          }
        }
      } else {
        for (let i = 0; i < VIDEO_CALL_PREFERENCES.length; i++) {
          const device = allDevices.find((item) =>
            item.type.toLowerCase().includes(VIDEO_CALL_PREFERENCES[i].toLowerCase())
          );
          if (device) {
            AudioMode.setAudioDevice(device?.uid || device.type);
            break;
          }
        }
      }
    }
  }

  addAudioDeviceListener = () => {
    this.unsubscribeAudioModeEventEmitter = this.AudioModeEventEmitter.addListener(
      AudioMode.DEVICE_CHANGE_EVENT,
      (allDevices) => {
        if (!this.isAudioDevicesInitialized) {
          this.setAudioDevices(allDevices);
          this.isAudioDevicesInitialized = true;
        }
        (this.context as IContext).dispatch({
          type: SET_AUDIO_MODES,
          payload: allDevices,
        });
        this.onAudioModeChanged(allDevices);
        (this.context as IContext).dispatch({
          type: SET_SELECTED_AUDIO_MODE,
          payload: allDevices.find((item) => item.selected)?.type,
        });
      }
    );

    if (Platform.OS === "ios") {
      this.unsubscribeAudioModeEventEmitterCustom = this.AudioModeEventEmitter.addListener(
        AudioMode.DEVICE_CHANGE_EVENT_CUSTOM,
        (selectedDevice) => {
          if ((this.context as IContext).users.length === 1) {
            const _allDevices = (this.context as IContext).globalState.audioModes.map((item) => {
              return {
                ...item,
                selected:
                  item.uid === selectedDevice || item.type === selectedDevice ? true : false,
              };
            });
            (this.context as IContext).dispatch({
              type: SET_AUDIO_MODES,
              payload: _allDevices,
            });
            this.onAudioModeChanged(_allDevices);
            (this.context as IContext).dispatch({
              type: SET_SELECTED_AUDIO_MODE,
              payload: _allDevices.find((item) => item.selected)?.type,
            });
          }
        }
      );
    }
  };

  addListeners = () => {
    const { jitsiManager }: any = this.context;
    this.endCall = this.eventEmitter.addListener("EVENT_END_CALL_SESSION", (type) => {
      jitsiManager.current.leave();
    });
    if (Platform.OS === "android") {
      this.cameraAvailability = this.eventEmitter.addListener(
        "EVENT_CAMERA_AVAILABILITY",
        debounce((event) => {
          console.log(TAG, "EVENT_CAMERA_AVAILABILITY", event);
          if (globalSharedObject.cameraManualTimeStamp + 4000 > Date.now()) {
            return; // Ignore camera availability event if camera was flipped recently
          }
          const users = (this.context as IContext).users;
          if (users.length > 0) {
            if (event.type === "available" && !users[0].isVideoMuted) {
              globalSharedObject.cameraManualTimeStamp = Date.now();
              users[0].videoTrack?.mute();
              setTimeout(() => {
                users[0].videoTrack.unmute();
              }, 1000);
            }
          }
        }, 1000)
      );
    }
    this.switchCameraSource = this.eventEmitter.addListener(
      "EVENT_SWITCH_CAMERA_SOURCE",
      (type) => {
        jitsiManager.current.flipCamera();
      }
    );
    this.muteAudio = this.eventEmitter.addListener("EVENT_MUTE_AUDIO", (type) => {
      jitsiManager.current.muteAudio();
    });
    this.unMuteAudio = this.eventEmitter.addListener("EVENT_UNMUTE_AUDIO", (type) => {
      jitsiManager.current.unMuteAudio();
    });
    this.pauseVideo = this.eventEmitter.addListener("EVENT_PAUSE_VIDEO", (type) => {
      jitsiManager.current.muteVideo();
    });
    this.unPauseVideo = this.eventEmitter.addListener("EVENT_UNPAUSE_VIDEO", (type) => {
      jitsiManager.current.unMuteVideo();
    });
    // TODO:Add audio mode
    this.changeAudiModeToSpeaker = this.eventEmitter.addListener(
      "EVENT_AUDIO_MODE_SPEAKER",
      (type) => {
        this.setAudioMode("SPEAKER");
      }
    );
    this.changeAudiModeToEarpiece = this.eventEmitter.addListener(
      "EVENT_AUDIO_MODE_EARPIECE",
      (type) => {
        this.setAudioMode("EARPIECE");
      }
    );
    this.changeAudiModeToEarpiece = this.eventEmitter.addListener(
      "EVENT_AUDIO_MODE_HEADPHONES",
      (type) => {
        this.setAudioMode("HEADPHONES");
      }
    );
    this.changeAudiModeToEarpiece = this.eventEmitter.addListener(
      "EVENT_AUDIO_MODE_BLUETOOTH",
      (type) => {
        this.setAudioMode("BLUETOOTH");
      }
    );
    // TODO: need to remove this event
    this.unmountComponent = this.eventEmitter.addListener("EVENT_UNMOUNT_COMPONENT", (type) => {});
    this.remountComponent = this.eventEmitter.addListener("EVENT_REMOUNT_COMPONENT", (type) => {});

    this.enterPipMode = this.eventEmitter.addListener("EVENT_ENTER_PIP_MODE", (prams) => {
      jitsiManager.current.enterPipMode();
    });
    this.exitPipMode = this.eventEmitter.addListener("EVENT_EXIT_PIP_MODE", (prams) => {
      jitsiManager.current.exitPipMode();
    });
    this.switchToVideoCall = this.eventEmitter.addListener(
      "EVENT_SWITCH_TO_VIDEO_CALL",
      (prams) => {
        jitsiManager.current.requestingToSwitchToVideoCall();
      }
    );
    this.startCallRecording = this.eventEmitter.addListener(
      "EVENT_START_CALL_RECORDING",
      (prams) => {
        jitsiManager.current.startRecording();
      }
    );
    this.eventEmitter.addListener("EVENT_SET_AUDIO_MODE", (prams) => {
      this.setAudioMode(prams.audioMode);
    });
    this.eventEmitter.addListener("EVENT_GET_AUDIO_MODES", () => {
      this.getAudioModes().then((res: any) => {
        CometChatRTC.getAudioModesOnSuccess(res.modes);
      });
    });
    this.stopCallRecording = this.eventEmitter.addListener("EVENT_STOP_CALL_RECORDING", (prams) => {
      jitsiManager.current.stopRecording();
    });
  };

  onEndCall() {
    if (this.settings?.onEndCall) this.settings.onEndCall();
    Logger.d(TAG, "[onEndCall]");
    if (CometChatRTC) CometChatRTC.onCallEnded();
  }

  onCallEndButtonPressed() {
    if (this.settings?.onCallEndButtonPressed) this.settings.onCallEndButtonPressed();

    if (CometChatRTC) {
      CometChatRTC.onCallEndButtonPressed();
    }
  }

  onConnectionInterrupted() {
    if (this.settings?.onConnectionInterrupted) this.settings.onConnectionInterrupted();

    if (CometChatRTC) {
      CometChatRTC.onConnectionInterrupted();
    }
  }

  onConnectionRestored() {
    if (this.settings?.onConnectionRestored) this.settings.onConnectionRestored();

    if (CometChatRTC) {
      CometChatRTC.onConnectionRestored();
    }
  }

  onConnectionFailed() {
    if (this.settings?.onConnectionFailed) this.settings.onConnectionFailed();

    if (CometChatRTC) {
      CometChatRTC.onConnectionFailed();
    }
  }

  onConnectionDisconnected() {
    if (this.settings?.onConnectionDisconnected) this.settings.onConnectionDisconnected();

    if (CometChatRTC) {
      CometChatRTC.onConnectionDisconnected();
    }
  }

  onSessionTimeout() {
    if (typeof this.settings?.onSessionTimeout === "function") this.settings.onSessionTimeout();
    if (typeof CometChatRTC?.onSessionTimeout === "function") CometChatRTC.onSessionTimeout();
  }

  onUserJoined(user: IUser) {
    if (this.settings?.onUserJoined) this.settings?.onUserJoined(removeTracksFromUserObject(user));
    if (CometChatRTC)
      if (CometChatRTC.onUserJoined) CometChatRTC?.onUserJoined(removeTracksFromUserObject(user));
  }

  onUserLeft(user: IUser) {
    if (this.settings?.onUserLeft) this.settings.onUserLeft(removeTracksFromUserObject(user));

    // console.log("i am called onUserLeft", removeTracksFromUserObject(user));
    if (CometChatRTC)
      if (CometChatRTC?.onUserLeft) CometChatRTC.onUserLeft(removeTracksFromUserObject(user));
  }

  onUserListChanged(list: IUser[]) {
    const userList = removeTracksFromUserList(list);
    if (JSON.stringify(userList) != JSON.stringify(this.userList)) {
      this.userList = userList;
      if (this.settings?.onUserListChanged) this.settings.onUserListChanged(userList);
      // console.log("i am called ", removeTracksFromUserList(list));
      if (CometChatRTC) CometChatRTC.onUserListChanged(userList);
    }
  }
  // TODO: add audio mode
  onAudioModeChanged(list: any) {
    (this.context as IContext).dispatch({
      type: SET_AUDIO_MODES,
      payload: list,
    });
    if (
      this.audioDevices.length !== list.length ||
      JSON.stringify(this.audioDevices) !== JSON.stringify(list)
    ) {
      if (this.settings?.onAudioModeChanged) this.settings.onAudioModeChanged(list);
      if (this.audioModeEventTimer) {
        clearTimeout(this.audioModeEventTimer);
      }
      this.audioModeEventTimer = setTimeout(() => {
        if (JSON.stringify(list) === JSON.stringify(this.previousAudioModeListToComarpe)) {
          return;
        }
        if (CometChatRTC) CometChatRTC.onAudioModeChanged(list);
        this.previousAudioModeListToComarpe = list;
        this.audioModeEventTimer = null;
      }, 600);
    }
    this.audioDevices = list;
  }

  getAudioModesOnSuccess(list: any) {
    (this.context as IContext).dispatch({
      type: SET_AUDIO_MODES,
      payload: list,
    });
    if (this.settings?.getAudioModesOnSuccess) this.settings.getAudioModesOnSuccess(list);
    if (CometChatRTC) CometChatRTC.getAudioModesOnSuccess(list);
  }
  onSwitchedToVideoCall(info: { sessionId: string; initiator: IUser; responder: IUser }) {
    if (this.settings?.onCallSwitchedToVideo)
      this.settings.onCallSwitchedToVideo({
        initiator: info.initiator,
        accepted: info.responder,
        sessionId: info.sessionId,
      });
    if (CometChatRTC)
      CometChatRTC.onCallSwitchedToVideo(info.sessionId, info.initiator, info.responder);
  }

  onRecordingToggled = (recordingInfo: { recordingStarted: boolean; user: IUser }) => {
    if (this.settings?.onRecordingToggled) this.settings.onRecordingToggled(recordingInfo);
    if (CometChatRTC) CometChatRTC.onRecordingToggled(recordingInfo);
  };

  onUserMuted = (mutedInfo: { muted: IUser; mutedBy: IUser }) => {
    if (this.settings?.onUserMuted) this.settings.onUserMuted(mutedInfo);
    if (CometChatRTC) if (CometChatRTC?.onUserMuted) CometChatRTC?.onUserMuted(mutedInfo);
  };

  removeListener = () => {
    this.endCall?.remove();
    Platform.OS === "android" && this.cameraAvailability?.remove();
    this.switchCameraSource?.remove();
    this.unsubscribeAudioModeEventEmitter?.remove();
    this.unsubscribeAudioModeEventEmitterCustom?.remove();
    this.muteAudio?.remove();
    this.unMuteAudio?.remove();
    this.pauseVideo?.remove();
    this.unPauseVideo?.remove();
    this.changeAudiModeToSpeaker?.remove();
    this.changeAudiModeToEarpiece?.remove();
    this.unmountComponent?.remove();
    this.remountComponent?.remove();
    this.enterPipMode?.remove();
    this.exitPipMode?.remove();
    this.switchToVideoCall?.remove();
    this.startCallRecording?.remove();
    this.stopCallRecording?.remove();
  };

  render() {
    return null;
  }
}

