  debounce = (func, delay) => {
    let debounceTimer;
    return function () {
      // eslint-disable-next-line no-invalid-this
      const context = this;
      // eslint-disable-next-line prefer-rest-params
      const args = arguments;
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => func.apply(context, args), delay);
    };
  };

  sortArrayWithOtherArray = (array: Array<any>, sortingArray: Array<String>) => {
    const { globalRef }: any = this.context;

    const result1 = [];
    const result2 = [];
    const temp = [];
    for (let i = 1; i < array.length; i++) {
      if (array[i]?.id === globalRef.current?.dominantSpeakerId) {
        temp.push(array[i]);
      } else if (sortingArray.includes(array[i].id)) {
        result1.push(array[i]);
      } else {
        result2.push(array[i]);
      }
    }
    // console.log(result1, result2,temp)
    return [
      array[0],
      ...result1.sort((product1, product2) => {
        const index1 = sortingArray.indexOf(product1.id);
        const index2 = sortingArray.indexOf(product2.id);
        return (index1 > -1 ? index1 : Infinity) - (index2 > -1 ? index2 : Infinity);
      }),
      ...result2,
      ...temp,
    ];
  };

