  leave = async () => {
    try {
      if (Platform.OS === "android") {
        NativeModules.CallNotificationService.stopService();
        NativeModules.PictureInPictureModule.exitPictureInPictureMode();
      }
      NativeModules.CometChatCommonModule.unlockAllOrientations();
      if (this.alreadyLeft) return;
      this.alreadyLeft = true;
      if (!this.localUserEndsCall) this.localUserEndsCall = true;
      const { nativeManager }: any = this.context;
      this.unsubscribeFromNetInfo();
      await this.unload();
      Logger.d(TAG, "[leave]");
      this.room
        ?.leave()
        .then(() => {})
        .catch()
        .finally(() => {
          this.connection?.disconnect();
          if (nativeManager.current?.removeListener) nativeManager.current?.removeListener();
        });
    } catch (error) {
      Logger.e(TAG, "[leave]", error);
    }
  };

