import React, { useState, useEffect, useRef, useMemo, ReactNode } from "react";
import {
  View,
  Text,
  PanResponder,
  Animated,
  Image,
  LayoutAnimation,
  Platform,
  UIManager,
} from "react-native";
// import localStyles from "../MainVideo/mainVideoStyles";
// import Logger from "../../lib/Logger";
import { Avatar } from "..";
import { RTCView } from "react-native-webrtc";
// import Users from "../MainVideo/Users";
import { useStore } from "../../store/Store";
import { stringToColor } from "../../utils/helper";
import { getStatusBarHeight } from "../../utils/getStatusBarHeight";
const VIDEO_TILE_HEIGHT = 150;
const VIDEO_TILE_WIDTH = 100;
const BOTTOM_SPACE = Platform.OS === "android" ? 100 : 150;
const minX = VIDEO_TILE_WIDTH / 2 + 10;
const minY = VIDEO_TILE_HEIGHT / 2 + 10;
if (Platform.OS === "android") {
  if (UIManager.setLayoutAnimationEnabledExperimental) {
    UIManager.setLayoutAnimationEnabledExperimental(true);
  }
}

interface PanAnimatedValue extends Animated.Value {
  _value: number;
}

let numberOfRender = 0;
function Spotlight() {
  const {
    globalState,
    users,
    settings: callSettings,
    setSettings,
    jitsiManager,
    settings: {
      avatarMode,
      videoSettings: { videoFit, nameLabel, userListButton, zoomButton },
    },
  } = useStore();
  const statusBarHeight = getStatusBarHeight(false);
  const pan = useRef(new Animated.ValueXY()).current;
  const panXY = useRef({ x: 0, y: 0 });
  const moveX = useRef(0);
  const moveY = useRef(0);
  const maxX = useRef(globalState.dimension.width - minX);
  const maxY = useRef(globalState.dimension.height - minY - BOTTOM_SPACE);
  numberOfRender++;
  console.log("Spotlight numberOfRender:", numberOfRender);
  const panResponder = useMemo(() => {
    maxX.current =
      globalState.dimension.width - minX - (!globalState.isPortrait ? BOTTOM_SPACE : 0);
    maxY.current =
      globalState.dimension.height - minY - (globalState.isPortrait ? BOTTOM_SPACE : 0);
    return PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: (evt, gestureState) => true,
      onPanResponderGrant: (e, gestureState) => {
        pan.setOffset({
          x: (pan.x as PanAnimatedValue)._value,
          y: (pan.y as PanAnimatedValue)._value,
        });
        pan.setValue({ x: 0, y: 0 });
      },
      onPanResponderMove: (event, gestureState) => {
        if (callSettings.enableDraggableVideoTile === false) return;
        if (panXY.current.x < maxX.current && panXY.current.y < maxY.current) {
          pan.setValue({ x: gestureState.dx, y: gestureState.dy });
          moveX.current = gestureState.moveX;
          moveY.current = gestureState.moveY;
        }
      },
      onPanResponderRelease: (e, gestureState) => {
        if (
          gestureState.dx === 0 &&
          gestureState.dy === 0 &&
          gestureState.vx === 0 &&
          gestureState.vy === 0
        ) {
          if (callSettings.enableVideoTileClick) setVideoFlipped((prev) => !prev);
        }
        pan.flattenOffset();
        if (panXY.current.x > maxX.current || panXY.current.y > maxY.current) {
          pan.setValue({ x: moveX.current - 100, y: moveY.current - 100 });
        }
      },
    });
  }, [globalState.dimension.width]);

  useEffect(() => {
    pan.addListener((e) => {
      panXY.current = { x: e.x, y: e.y };
    });
  }, []);
  useEffect(() => {
    pan.setValue({
      x: maxX.current - VIDEO_TILE_WIDTH / 2,
      y: minY - VIDEO_TILE_HEIGHT / 2,
    });
  }, [globalState.dimension.width]);
  const [isVideoFlipped, setVideoFlipped] = useState(false);
  const renderMainVideo = () => {
    let mainUser: any = null;
    if (isVideoFlipped || users.length == 1) {
      mainUser = users[0];
    } else {
      if (users?.length == 2) {
        mainUser = users[1];
      } else {
        if (globalState.pinnedUserId) {
          mainUser = users.find((user: IUser) => user.id === globalState.pinnedUserId);
        } else if (globalState.dominantSpeakerId) {
          mainUser = users.find((user: IUser) => user.id === globalState.dominantSpeakerId);
        }
        if (!mainUser) {
          mainUser = users[1];
        }
      }
    }
    if (!mainUser) {
      return false;
    }
    const otherUsers: ReactNode[] = [];
    const userListButtonFun = () => (
      <UserListButton
        userLength={users.length}
        onButtonPress={() => {
          LayoutAnimation.configureNext(LayoutAnimation.Presets.linear);
          LayoutAnimation.configureNext({
            duration: 100,
            create: { type: "linear", property: "scaleY" },
            update: { type: "linear", property: "scaleY" },
            delete: { type: "linear", property: "opacity" },
          });
        }}
      />
    );
    const renderUserStats = () => (
      <View
        style={{
          paddingRight: 5,
          flexDirection: "row",
        }}
      >
        <Text
          style={{
            color: color.palette.white,
            fontSize: 18,
            fontWeight: "bold",
          }}
        >
          {mainUser.name}
        </Text>
        {mainUser.isAudioMuted ? (
          <View
            style={{
              width: 10,
              height: 10,
              marginLeft: 5,
              // backgroundColor: "#c0c0c0",
              borderRadius: 20,
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Image style={{ width: 15, height: 15 }} source={ICONS.AUDIO_MUTE} />
          </View>
        ) : null}

        {mainUser.isVideoMuted && !callSettings.isAudioOnly ? (
          <View
            style={{
              width: 10,
              height: 10,
              marginLeft: 5,
              // backgroundColor: "#c0c0c0",
              borderRadius: 20,
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Image style={{ width: 15, height: 15 }} source={ICONS.VIDEO_MUTE} />
          </View>
        ) : null}
      </View>
    );
    const zoomButtonFun = () => (
      <ZoomButton
        onButtonPress={() => {
          console.log("zoomButtonFun>>>");

          LayoutAnimation.configureNext(LayoutAnimation.Presets.linear);
          LayoutAnimation.configureNext({
            duration: 200,
            create: { type: "linear", property: "scaleY" },
            update: { type: "linear", property: "scaleY" },
            delete: { type: "linear", property: "opacity" },
          });

          setSettings({
            type: TOGGLE_VIDEO_FIT,
            payload: videoFit === "cover" ? "contain" : "cover",
          });
        }}
        videoFit={videoFit}
      />
    );

    const mainVideoItems = () => (
      <>
        <View style={[localStyles.videoItemContainer, { top: 0 }]}>
          <View style={{ flex: 1 }}>
            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  top: 0,
                  left: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "top-left" && renderUserStats()}

              {userListButton?.visibility &&
                userListButton.position === "top-left" &&
                users.length > 2 &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "top-left" && zoomButtonFun()}
            </View>

            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  top: 0,
                  right: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "top-right" && renderUserStats()}
              {userListButton?.visibility &&
                userListButton.position === "top-right" &&
                users.length > 2 &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "top-right" && zoomButtonFun()}
            </View>
          </View>
        </View>
        <View style={[localStyles.videoItemContainer, { bottom: 0 }]}>
          <View style={{ flex: 1 }}>
            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  bottom: 0,
                  left: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "bottom-left" && renderUserStats()}
              {userListButton?.visibility &&
                userListButton.position === "bottom-left" &&
                users.length > 2 &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "bottom-left" && zoomButtonFun()}
            </View>
            <View
              style={[
                localStyles.videoInnerContainer,
                {
                  bottom: 0,
                  right: 0,
                },
              ]}
            >
              {nameLabel?.visibility && nameLabel.position === "bottom-right" && renderUserStats()}
              {userListButton?.visibility &&
                userListButton.position === "bottom-right" &&
                users.length > 2 &&
                userListButtonFun()}
              {zoomButton?.visibility && zoomButton.position === "bottom-right" && zoomButtonFun()}
            </View>
          </View>
        </View>
      </>
    );
    if (users.length > 2) {
      (users as any[]).map((user, index) => {
        if (index != 0 && user.id != mainUser.id && !user.isAudioMuted && user.audioTrack) {
          otherUsers.push(
            <RTCView
              key={user.id}
              objectFit='cover'
              streamURL={user.audioTrack?.getOriginalStream().toURL()}
              style={localStyles.zero_height_width}
              zOrder={-10}
            />
          );
        }
      });
    }

    if (mainUser.videoTrack && !mainUser.isVideoMuted) {
      const sourceName = mainUser.videoTrack?.getSourceName?.();
      jitsiManager?.current?.setConstraints(sourceName);
      return (
        <View style={{ flex: 1, height: "100%", width: "100%" }}>
          {otherUsers?.length ? otherUsers.map((user) => <>{user}</>) : null}
          <RTCView
            key={mainUser?.id}
            objectFit={videoFit === "cover" ? "cover" : "contain"}
            streamURL={mainUser?.videoTrack.getOriginalStream().toURL()}
            style={localStyles.full_height_width}
            zOrder={-10}
            mirror={
              users[0].id === mainUser.id
                ? mainUser?.videoTrack?._facingMode === "environment"
                  ? false
                  : true
                : false
            }
          />
          {mainVideoItems()}
        </View>
      );
    }

    return (
      <View style={localStyles.main_video_avatar_main_view}>
        {otherUsers?.length ? otherUsers.map((user) => <>{user}</>) : null}
        <Avatar
          backgroundColor={stringToColor(mainUser?.name)}
          textColor={"#FFF"}
          size={100}
          avatar={mainUser.avatar}
        >
          {mainUser.name}
        </Avatar>
        {/* {avatarMode == "fullscreen" ? (
          <View style={{ position: "absolute", bottom: 25, left: 5 }}>
            <AudioLevelIndicator track={mainUser.audioTrack} />
          </View>
        ) : (
          <AudioLevelIndicator track={mainUser.audioTrack} />
        )} */}
        <RTCView
          key={mainUser.id}
          objectFit={videoFit === "cover" ? "cover" : "contain"}
          streamURL={mainUser.audioTrack?.getOriginalStream().toURL()}
          style={localStyles.zero_height_width}
          zOrder={0}
        />
        {mainVideoItems()}
      </View>
    );
  };

  const localVideoView = () => {
    let localUser = null;
    if (!isVideoFlipped) {
      localUser = users[0];
    } else {
      if (users?.length == 2) {
        localUser = users[1];
      } else {
        if (globalState.pinnedUserId) {
          localUser = users.find((user) => user.id === globalState.pinnedUserId);
        } else if (globalState.dominantSpeakerId) {
          localUser = users.find((user) => user.id === globalState.dominantSpeakerId);
        }
        if (!localUser) {
          localUser = users[1];
        }
      }
    }
    if (!localUser || users.length == 1) {
      return null;
    }
    if (localUser.videoTrack && !localUser.isVideoMuted) {
      return (
        <View
          style={{
            height: "100%",
            width: "100%",

            backgroundColor: "#2E2F30",

            borderRadius: 8,
            overflow: "hidden",
          }}
        >
          <View
            style={{
              justifyContent: "flex-start",
              alignItems: "center",
              position: "absolute",
              left: 5,
              bottom: 5,
              zIndex: 5,
              elevation: 5,
            }}
          >
            {localUser.isAudioMuted ? (
              <View
                style={{
                  width: 10,
                  height: 10,
                  margin: 2,
                  // backgroundColor: "#c0c0c0",
                  borderRadius: 20,
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Image style={{ width: 15, height: 15 }} source={ICONS.AUDIO_MUTE} />
              </View>
            ) : null}

            {localUser.isVideoMuted && !callSettings.isAudioOnly ? (
              <View
                style={{
                  width: 10,
                  height: 10,
                  margin: 2,
                  borderRadius: 20,
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Image style={{ width: 15, height: 15 }} source={ICONS.VIDEO_MUTE} />
              </View>
            ) : null}
          </View>
          <RTCView
            objectFit='cover'
            streamURL={localUser?.videoTrack.getOriginalStream().toURL()}
            style={localStyles.full_height_width}
            zOrder={1}
            mirror={
              users[0].id === localUser.id
                ? localUser?.videoTrack?._facingMode === "environment"
                  ? false
                  : true
                : false
            }
          />
        </View>
      );
    }
    return (
      <View
        style={{
          backgroundColor: "#2E2F30",
          height: "100%",
          width: "100%",
          borderRadius: 8,
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <View
          style={{
            justifyContent: "flex-start",
            alignItems: "center",
            position: "absolute",
            right: 5,
            bottom: 5,
            zIndex: 5,
            elevation: 5,
          }}
        >
          {localUser.isAudioMuted ? (
            <View
              style={{
                width: 10,
                height: 10,
                margin: 2,
                borderRadius: 20,
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Image style={{ width: 15, height: 15 }} source={ICONS.AUDIO_MUTE} />
            </View>
          ) : null}
        </View>
        <Avatar backgroundColor={"#4d4c4f"} textColor={"#FFF"} size={30} avatar={localUser.avatar}>
          {localUser.name}
        </Avatar>
        <Text
          numberOfLines={1}
          ellipsizeMode={"tail"}
          style={[
            { fontSize: 14, color: "#fff", position: "absolute" },
            avatarMode == "fullscreen" ? { top: 5, left: 5 } : { bottom: 0, left: 0 },
          ]}
        >
          {localUser.name}
        </Text>

        {/* <AudioLevelIndicator track={localUser.audioTrack} /> */}
        <RTCView
          key={localUser.id}
          objectFit='cover'
          streamURL={localUser.audioTrack?.getOriginalStream().toURL()}
          style={localStyles.zero_height_width}
          zOrder={-10}
        />
      </View>
    );
  };

  return (
    <View
      style={{
        flex: 1,

        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "#000",
      }}
    >
      {renderMainVideo()}
      <Animated.View
        style={{
          marginTop: statusBarHeight,
          position: "absolute",
          top: "0%",
          left: "0%",
          height: VIDEO_TILE_HEIGHT,
          width: VIDEO_TILE_WIDTH,
          transform: [
            {
              translateX: pan.x.interpolate({
                inputRange: [10, maxX.current - VIDEO_TILE_WIDTH / 2],
                outputRange: [10, maxX.current - VIDEO_TILE_WIDTH / 2],
                extrapolate: "clamp",
              }),
            },
            {
              translateY: pan.y.interpolate({
                inputRange: [10, maxY.current - VIDEO_TILE_HEIGHT],
                outputRange: [10, maxY.current - VIDEO_TILE_HEIGHT],
                extrapolate: "clamp",
              }),
            },
          ],
        }}
        {...panResponder.panHandlers}
      >
        {localVideoView()}
      </Animated.View>
    </View>
  );
}

export default Spotlight;

import { StyleSheet } from "react-native";
import IUser from "../../Types/Users";
import { ICONS } from "../../icons";
import { color } from "../../theme/color";
import { ZoomButton } from "../MainVideoItems/ZoomButton";
import { TOGGLE_VIDEO_FIT } from "../../store/ActionType";
import { UserListButton } from "../MainVideoItems/UserListButton";

const localStyles = StyleSheet.create({
  main_video_avatar_main_view: {
    height: "100%",
    width: "100%",
    alignItems: "center",
    justifyContent: "center",
    flexDirection: "column",
  },
  zero_height_width: { height: "0%", width: "0%" },
  full_height_width: { height: "100%", width: "100%" },
  videoItemContainer: {
    position: "absolute",
    paddingVertical: 5,
    paddingHorizontal: 5,
    width: "100%",
    height: 55,
  },
  videoInnerContainer: {
    position: "absolute",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
  },
});
