import React, { useCallback, useEffect, useRef, useState } from "react";
import { FlatList, TouchableOpacity, View, Text, Image, LayoutAnimation } from "react-native";
import { color } from "../../theme";
import { ICONS } from "../../icons";
import { SET_PINNED_USER, TOGGLE_PARTICIPANTS_MODEL } from "../../store/ActionType";
import { useStore } from "../../store/Store";
import IUser from "../../Types/Users";
import localStyles from "./Participants.styles";
import NetworkComp from "./NetworkComp";

let timer: any = null;

const UserFlatlist = React.memo(
  ({
    pinnedUserId,
    itemsRef,
    isMenuVisible,
    setIsMenuVisible,
    recorderId,
    isAudioOnly,
    selectedIndexRef,
    topRef,
    dispatch,
    headerRef,
    refresh,
    users,
    screenOffsetRef,
  }: {
    pinnedUserId: any;
    itemsRef: any;
    isMenuVisible: any;
    setIsMenuVisible: any;
    recorderId: any;
    isAudioOnly: any;
    selectedIndexRef: any;
    topRef: any;
    dispatch: any;
    headerRef: any;
    refresh: boolean;
    users: any;
    screenOffsetRef: any;
  }) => {
    const renderUserItem = (userItem) => {
      if (userItem) {
        const user = userItem.item;
        const index = userItem.index;
        let username = user.name;
        let isPinned;

        if (index == 0) {
          username += " (you)";
        }

        if (user.id === pinnedUserId) {
          isPinned = true;
        } else {
          isPinned = false;
        }

        return (
          <>
            <TouchableOpacity
              onPress={() => {
                setIsMenuVisible(false);
              }}
              activeOpacity={1}
              style={localStyles.user_item_container}
            >
              <View style={localStyles.user_item_pinned}>
                <View>{user.id === recorderId && <View style={localStyles.recorderBadge} />}</View>
                <Text testID={`cc-user${index}-name`} style={localStyles.user_item_user_name}>
                  {username}
                </Text>

                <View style={localStyles.user_item_icon_container}>
                  <View
                    style={[
                      localStyles.users_icons_container,
                      {
                        flexDirection: "row",
                        alignItems: "center",
                      },
                    ]}
                  >
                    {global.ccUsersStats[user.id] && (
                      <NetworkComp connectionQuality={global.ccUsersStats[user.id]} />
                    )}
                  </View>
                  <View
                    testID={`cc-user${index}-audio-icon`}
                    style={localStyles.users_icons_container}
                  >
                    <Image
                      style={[
                        localStyles.user_item_icons,
                        { tintColor: user.isAudioMuted ? color.red : color.green },
                      ]}
                      source={user.isAudioMuted ? ICONS.AUDIO_MUTE : ICONS.AUDIO_UNMUTE}
                    />
                  </View>
                  {isAudioOnly ? null : (
                    <View
                      testID={`cc-user${index}-video-icon`}
                      style={localStyles.users_icons_container}
                    >
                      <Image
                        style={[
                          localStyles.user_item_icons,
                          { tintColor: user.isVideoMuted ? color.red : color.green },
                        ]}
                        source={user.isVideoMuted ? ICONS.VIDEO_MUTE : ICONS.VIDEO_UNMUTE}
                      />
                    </View>
                  )}

                  {user.status === "interrupted" ? (
                    <View style={localStyles.users_icons_container}>
                      <Image style={localStyles.user_item_icons} source={ICONS.ALERT} />
                    </View>
                  ) : null}

                  {isPinned ? (
                    <View
                      testID={`cc-user${index}-pin-icon`}
                      style={localStyles.users_icons_container}
                    >
                      <Image style={localStyles.user_item_icons} source={ICONS.PIN} />
                    </View>
                  ) : null}
                  <TouchableOpacity
                    testID={`cc-user${index}-opt`}
                    style={localStyles.users_icons_container}
                    onPress={(e) => {
                      const pageY = e.nativeEvent.pageY;
                      const locationY = e.nativeEvent.locationY;
                      itemsRef.current?.measure((x, y, w, h, px, py) => {
                        topRef.current = pageY + locationY - py;
                        selectedIndexRef.current = index;
                        setIsMenuVisible((prev) => !prev);
                      });
                    }}
                  >
                    <Image
                      // resizeMode="contain"
                      source={ICONS.MENU}
                      style={[{ height: 20, width: 20 }]}
                    />
                  </TouchableOpacity>
                </View>
              </View>
            </TouchableOpacity>
          </>
        );
      }
    };
    return (
      <FlatList
        style={localStyles.flat_list_style}
        data={users}
        keyExtractor={(user) => user.id}
        renderItem={renderUserItem}
        // extraData={refresh}
        onScroll={() => {
          if (isMenuVisible) {
            const animation = LayoutAnimation.create(
              300,
              LayoutAnimation.Types.easeOut,
              LayoutAnimation.Properties.scaleXY
            );
            LayoutAnimation.configureNext(animation);
            setIsMenuVisible(false);
          }
        }}
        ListHeaderComponent={() => (
          <View
            style={localStyles.user_item_pinned}
            ref={headerRef}
            onLayout={() => {
              headerRef.current?.measure((fx, fy, width, height, px, py) => {
                screenOffsetRef.current = py;
              });
            }}
          >
            <TouchableOpacity
              testID='cc-user-list-close'
              touchSoundDisabled
              style={localStyles.user_list_close_container}
              onPress={() => {
                LayoutAnimation.configureNext({
                  duration: 100,
                  create: { type: "linear", property: "scaleY" },
                  update: { type: "linear", property: "scaleY" },
                  delete: { type: "linear", property: "opacity" },
                });
                dispatch({
                  type: TOGGLE_PARTICIPANTS_MODEL,
                  payload: false,
                });
                setIsMenuVisible(false);
              }}
            >
              <Image style={localStyles.close_icon} source={ICONS.CLEAR} />
            </TouchableOpacity>
            <Text style={{ fontSize: 22, fontWeight: "700", color: "#fff" }}>User List</Text>
          </View>
        )}
        ListFooterComponent={() => (
          <TouchableOpacity
            activeOpacity={1}
            onPress={() => {
              if (isMenuVisible) setIsMenuVisible(false);
            }}
            style={{ height: 80 }}
          />
        )}
      />
    );
  },
  (prev, next) => prev.refresh == next.refresh
);

function Participants() {
  const { globalState, settings, jitsiManager, users, dispatch } = useStore();
  const [refresh, setRefresh] = useState(true);
  const [isMenuVisible, setIsMenuVisible] = useState(false);
  const topRef = useRef(0);
  const screenOffsetRef = useRef(0);
  const headerRef = useRef(null);
  const selectedIndexRef = useRef(0);
  const itemsRef = useRef(null);

  const updateUsers = () => {
    setRefresh((prev) => !prev);
  };

  const pinnedUserId = globalState.pinnedUserId;
  // TODO: Property 'recorderId' does not exist on type 'IState'
  const recorderId = globalState.recorderId;
  const unPinUser = useCallback(() => {
    dispatch({
      type: SET_PINNED_USER,
      payload: "",
    });
  }, []);

  const pinUser = useCallback((user: IUser) => {
    dispatch({
      type: SET_PINNED_USER,
      payload: user.id,
    });
  }, []);

  useEffect(() => {
    if (timer) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      updateUsers();
    }, 500);
  }, [users, pinnedUserId, recorderId, isMenuVisible]);

  if (!globalState.isParticipantsModelVisible) {
    return null;
  }
  return (
    <View
      style={localStyles.user_list_container}
      ref={(ref) => {
        itemsRef.current = ref;
      }}
    >
      <>
        <UserFlatlist
          pinnedUserId={pinnedUserId}
          itemsRef={itemsRef}
          isMenuVisible={isMenuVisible}
          setIsMenuVisible={setIsMenuVisible}
          recorderId={recorderId}
          isAudioOnly={settings.isAudioOnly}
          selectedIndexRef={selectedIndexRef}
          topRef={topRef}
          dispatch={dispatch}
          headerRef={headerRef}
          refresh={refresh}
          users={users}
          screenOffsetRef={screenOffsetRef}
        />
        {isMenuVisible && (
          <View
            style={[
              localStyles.menu_container,
              {
                top: topRef.current,
              },
            ]}
          >
            <TouchableOpacity
              testID='cc-user-pin'
              onPress={() => {
                if (users[selectedIndexRef.current]?.id === pinnedUserId) {
                  unPinUser();
                } else {
                  pinUser(users[selectedIndexRef.current]);
                }
                setIsMenuVisible(false);
              }}
              style={localStyles.menu_list}
            >
              <Image style={localStyles.menu_icon} source={ICONS.PIN} />
              <Text style={localStyles.menu_text}>
                {users[selectedIndexRef.current]?.id === pinnedUserId ? "Unpin" : "Pin"}
              </Text>
            </TouchableOpacity>
            {users[selectedIndexRef.current]?.isAudioMuted ||
            users[selectedIndexRef.current]?.id === users[0]?.id ? null : (
              <TouchableOpacity
                testID='cc-user-mute'
                onPress={() => {
                  jitsiManager.current.muteParticipant(users[selectedIndexRef.current]);
                  setIsMenuVisible(false);
                }}
                style={localStyles.menu_list}
              >
                <Image style={localStyles.menu_icon} source={ICONS.AUDIO_MUTE} />
                <Text style={localStyles.menu_text}>Mute</Text>
              </TouchableOpacity>
            )}
          </View>
        )}
      </>
    </View>
  );
}

export default React.memo(Participants);
