import { SWITCH_TO_REQUEST_MODEL_TYPE } from "../utils/Constants";
import {
  ON_AUDIO_CONVERTED_TO_VIDEO_CALL,
  ON_CONFERENCE_JOINED,
  ON_CONNECTION_ERROR,
  ON_CONNECTION_SUCCESS,
  ON_REQUESTING_TO_SWITCH_TO_VIDEO_CALL,
  ON_SCREEN_ORIENTATION_CHANGED,
  ON_SCREEN_RECORDING_STARTED,
  ON_SCREEN_RECORDING_STOPPED,
  ON_SWITCH_TO_VIDEO_CALL_ACCEPTED,
  ON_SWITCH_TO_VIDEO_CALL_REJECTED,
  ON_SWITCH_TO_VIDEO_CALL_REQUESTED,
  ON_TRYING_TO_START_RECORDING,
  ON_TRYING_TO_STOP_RECORDING,
  SET_DIMENSION,
  SET_DOMINANT_SPEAKER,
  SET_PINNED_USER,
  SET_RECORDER,
  TOGGLE_PIP_MODE,
  UPDATE_NO_OF_SCREEN_SHARE_USER,
  SET_AUDIO_MODES,
  TOGGLE_AUDIO_MODE_MODEL,
  SET_SELECTED_AUDIO_MODE,
  UPDATE_LASTN_ID,
  TOGGLE_PARTICIPANTS_MODEL,
  TOGGLE_CAMERA,
  ON_CONFERENCE_FAILED,
  TOGGLE_END_CALL_DIALOG,
  ON_CONNECTION_INTERRUPTED,
  ON_CONNECTION_RESTORED,
  ON_NETWORK_CHANGED,
} from "./ActionType";
import { IGlobalAction, IState } from "./GlobalState.types";

export const initialGlobalState: IState = {
  showAudioModel: false,
  dimension: { height: 500, width: 300 },
  dominantSpeakerId: "",
  connectionSuccess: false,
  connectionError: false,
  connectionLost: false,
  noNetwork: false,
  pinnedUserId: "",
  conferenceJoined: false,
  recorder: null,
  recordId: "",
  recorderId: "",
  isRecording: false,
  tryingToStartRecording: false,
  inPIPMode: false,
  isPortrait: true,
  switchToVideoCallRequestInitiator: null,
  switchedToVideoCall: false,
  showSwitchToVideoCallModel: false,
  switchToVideoRequestModelType: SWITCH_TO_REQUEST_MODEL_TYPE.INITIAL,
  switchToVideoCallRequestResponder: null,
  noOfScreenShareUser: 0,
  audioModes: [],
  mode: "TILE",
  selectedAudioMode: "SPEAKER",
  LastNId: [],
  isParticipantsModelVisible: false,
  cameraFlipped: true,
  connectionErrorType: "",
  showEndCallDialog: false,
};

export const reducer = (state: IState, { type, payload }: IGlobalAction): IState => {
  console.log("global reducer", type);
  switch (type) {
    case TOGGLE_END_CALL_DIALOG:
      return {
        ...state,
        showEndCallDialog: payload,
      };
    case TOGGLE_CAMERA:
      return {
        ...state,
        cameraFlipped: payload,
      };
    case TOGGLE_PARTICIPANTS_MODEL:
      return {
        ...state,
        isParticipantsModelVisible: payload,
      };
    case UPDATE_LASTN_ID:
      return {
        ...state,
        LastNId: payload,
      };
    case SET_SELECTED_AUDIO_MODE:
      return {
        ...state,
        selectedAudioMode: payload,
      };
    case TOGGLE_AUDIO_MODE_MODEL:
      return {
        ...state,
        showAudioModel: payload,
      };
    case SET_AUDIO_MODES:
      return {
        ...state,
        audioModes: payload,
      };
    case SET_DIMENSION:
      return {
        ...state,
        dimension: payload,
        isPortrait: payload.height > payload.width,
      };
    case SET_DOMINANT_SPEAKER:
      return {
        ...state,
        dominantSpeakerId: payload,
      };
    case ON_CONNECTION_SUCCESS:
      return {
        ...state,
        dominantSpeakerId: payload,
        connectionSuccess: true,
        connectionError: false,
      };
    case ON_CONNECTION_ERROR:
      return {
        ...state,
        connectionError: payload.error,
        connectionErrorType: payload.type,
      };
    case SET_PINNED_USER:
      return {
        ...state,
        pinnedUserId: payload,
      };
    case ON_CONFERENCE_JOINED:
      return {
        ...state,
        conferenceJoined: true,
      };
    case ON_CONFERENCE_FAILED:
      return {
        ...state,
        conferenceJoined: false,
      };
    case ON_SCREEN_RECORDING_STARTED:
      return {
        ...state,
        recorder: payload,
        recordId: payload.recordId,
        recorderId: payload.id,
        isRecording: true,
        tryingToStartRecording: false,
      };
    case ON_TRYING_TO_START_RECORDING:
      return {
        ...state,
        tryingToStartRecording: true,
        recorder: payload,
      };

    case ON_TRYING_TO_STOP_RECORDING:
      return {
        ...state,
        tryingToStartRecording: false,
        recorder: payload,
      };
    case ON_SCREEN_RECORDING_STOPPED:
      return {
        ...state,
        recorder: null,
        recordId: "",
        recorderId: "",
        isRecording: false,
        tryingToStartRecording: false,
      };
    case ON_SCREEN_ORIENTATION_CHANGED:
      return {
        ...state,
        isPortrait: payload,
      };
    case ON_REQUESTING_TO_SWITCH_TO_VIDEO_CALL:
      return {
        ...state,
        showSwitchToVideoCallModel: true,
        switchToVideoRequestModelType: SWITCH_TO_REQUEST_MODEL_TYPE.REQUESTED,
        switchToVideoCallRequestInitiator: payload,
      };
    case ON_SWITCH_TO_VIDEO_CALL_REQUESTED:
      return {
        ...state,
        showSwitchToVideoCallModel: true,
        switchToVideoCallRequestInitiator: payload,
        switchToVideoRequestModelType: SWITCH_TO_REQUEST_MODEL_TYPE.INITIAL,
      };

    case ON_SWITCH_TO_VIDEO_CALL_ACCEPTED:
      return {
        ...state,
        switchToVideoCallRequestResponder: payload,
        showSwitchToVideoCallModel: false,
        switchedToVideoCall: true,
      };
    case ON_SWITCH_TO_VIDEO_CALL_REJECTED:
      return {
        ...state,
        showSwitchToVideoCallModel: false,
        switchToVideoCallRequestResponder: payload,
      };
    case ON_AUDIO_CONVERTED_TO_VIDEO_CALL:
      return {
        ...state,
        switchToVideoCallRequestInitiator: payload.switchToVideoCallRequestInitiator,
        switchToVideoCallRequestResponder: payload.switchToVideoCallRequestResponder,
        switchToVideoRequestModelType: SWITCH_TO_REQUEST_MODEL_TYPE.CONVERTED,
        showSwitchToVideoCallModel: true,
      };
    case UPDATE_NO_OF_SCREEN_SHARE_USER:
      return {
        ...state,
        noOfScreenShareUser: payload,
      };
    case SET_RECORDER:
      return {
        ...state,
        recorder: payload,
      };
    case TOGGLE_PIP_MODE:
      return {
        ...state,
        inPIPMode: payload,
      };
    case ON_CONNECTION_INTERRUPTED:
      return {
        ...state,
        connectionLost: true,
      };
    case ON_CONNECTION_RESTORED:
      return {
        ...state,
        connectionLost: false,
      };
    case ON_NETWORK_CHANGED:
      return {
        ...state,
        noNetwork: payload,
      };
    default:
      return { ...state };
  }
};
