import React from "react";
import { View, Text, TouchableOpacity, StyleSheet } from "react-native";
import { CALL_TIMEOUT_TIMER_IN_SEC, CALL_TIMEOUT_TYPE } from "../../utils/Constants";
import { useStore } from "../../store/Store";

export type CallTimeoutType = typeof CALL_TIMEOUT_TYPE[keyof typeof CALL_TIMEOUT_TYPE];

export interface CallTimeoutPopupProps {
  timeToLeaveInSec?: number;
  onStay: () => void;
  onLeave: (type: CallTimeoutType) => void;
}

const CallTimeoutModal: React.FC<CallTimeoutPopupProps> = ({
  onLeave,
  onStay,
  timeToLeaveInSec = CALL_TIMEOUT_TIMER_IN_SEC,
}) => {
  const [timeRemaining, setTimeRemaining] = React.useState(timeToLeaveInSec);
  const { globalRef } = useStore();
  const timerActive = timeRemaining > 0;

  const minutesRemaining = Math.floor(timeRemaining / 60);
  const formattedTimeLeft = `${minutesRemaining > 0 ? `${minutesRemaining}:` : ""}${(
    timeRemaining % 60
  )
    .toString()
    .padStart(2, "0")}`;

  const ceilMinutes = Math.ceil(timeRemaining / 60);

  React.useEffect(() => {
    const interval = setInterval(() => {
      setTimeRemaining((prev) => {
        if (globalRef.current.callEnded) {
          clearInterval(interval);
          return 0;
        }
        if (prev <= 1) {
          setTimeout(() => {
            onLeave(CALL_TIMEOUT_TYPE.TIMEOUT_AUTO);
          }, 0);
          clearInterval(interval);
        }
        return prev - 1;
      });
    }, 1000);

    return () => {
      console.log("Clearing interval", "clearInterval");
      clearInterval(interval);
    };
  }, []);

  return (
    <View style={[styles.overlay, timerActive ? {} : { backgroundColor: "#1c2226" }]}>
      <View style={styles.container}>
        {timerActive && (
          <View style={styles.timer}>
            <Text style={styles.timerText}>{formattedTimeLeft}</Text>
          </View>
        )}
        <Text style={styles.title}>{timerActive ? "Are you still there?" : "Meeting Ended"}</Text>
        {timerActive ? (
          <Text style={styles.description}>
            Looks like you are the only one here! This call will end in less than {ceilMinutes}{" "}
            minute
            {ceilMinutes > 1 ? "s" : ""}. Want to keep it going?
          </Text>
        ) : (
          <Text style={styles.description}>
            The call has ended as there were no participants. Click “Leave now” to exit the meeting.
          </Text>
        )}
        <View style={styles.buttonContainer}>
          <TouchableOpacity
            style={styles.leaveButton}
            onPress={() => {
              if (timerActive) {
                onLeave(CALL_TIMEOUT_TYPE.TIMEOUT_CLICK);
              } else {
                onLeave(CALL_TIMEOUT_TYPE.TIMEOUT_LEAVE);
              }
            }}
          >
            <Text style={styles.leaveText}>Leave now</Text>
          </TouchableOpacity>
          {timerActive && (
            <TouchableOpacity style={styles.stayButton} onPress={onStay}>
              <Text style={styles.stayText}>Stay in the call</Text>
            </TouchableOpacity>
          )}
        </View>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: "#141414CC",
    justifyContent: "center",
    alignItems: "center",
    position: "absolute",
    zIndex: 10,
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
  container: {
    width: 320,
    backgroundColor: "#1A1A1A",
    paddingHorizontal: 20,
    paddingVertical: 16,
    borderRadius: 20,
    alignItems: "center",
    borderColor: "#383838",
    borderWidth: 1,
    // backgroundColor: "red",
  },
  timer: {
    width: 80,
    height: 80,
    borderRadius: 40,
    backgroundColor: "#0f488e",
    justifyContent: "center",
    alignItems: "center",
    marginBottom: 20,
  },
  timerText: { color: "#FFF", fontSize: 18, fontWeight: "700" },
  title: { color: "#FFF", fontSize: 20, fontWeight: "500", marginBottom: 8 },
  description: {
    color: "#989898",
    textAlign: "center",
    fontSize: 14,
    fontWeight: "400",
    marginBottom: 20,
    lineHeight: 14 * 1.25,
  },
  buttonContainer: { flexDirection: "row" },
  leaveButton: {
    flex: 1,
    paddingVertical: 9,
    borderRadius: 8,
    borderColor: "#4C4C4C",
    borderWidth: 1,
    alignItems: "center",
    marginRight: 12,
  },
  leaveText: { color: "#FFF", fontSize: 12, fontWeight: "400" },
  stayButton: {
    flex: 1,
    paddingVertical: 10,
    borderRadius: 8,
    backgroundColor: "#1E79E7",
    borderColor: "#1E79E7",
    borderWidth: 1,
    alignItems: "center",
  },
  stayText: { color: "#FFF", fontSize: 12, fontWeight: "500" },
});

export default CallTimeoutModal;
