import React from "react";
import { TouchableOpacity, Image } from "react-native";
import { useStore } from "../../store/Store";
import style from "./Buttons.styles";
import Logger from "../../utils/Logger";
import { ICONS } from "../../icons";
const TAG = "SwitchToVideoCallButton";
export default function SwitchToVideoCallButton() {
  const { jitsiManager } = useStore();
  const onButtonPressed = () => {
    try {
      Logger.d(TAG, "[onButtonPressed]");
      jitsiManager.current.requestingToSwitchToVideoCall();
    } catch (error) {
      Logger.d(TAG, "[onButtonPressed]", error);
    }
  };
  return (
    <TouchableOpacity
      testID='cc-switch-video'
      onPress={onButtonPressed}
      style={[style.buttonContainer]}
    >
      <Image style={style.buttonIcon} source={ICONS.SWITCH_TO_VIDEO_CALL} />
    </TouchableOpacity>
  );
}
