import { UIMode } from "./Constants";

export const globalSharedObject = {
  cameraManualTimeStamp: 0,
};

const sharedObjectOriginal = {
  mode: "DEFAULT",
  isPresenter: false,
};

const handler = {
  get(target, prop, receiver) {
    if (prop === "isPresenter") {
      if (target.mode === UIMode.PRESENTER) {
        return target.isPresenter ? true : false;
      }
      return undefined;
    }
    return Reflect.get(target, prop, receiver);
  },
};

export const sharedObject = new Proxy(sharedObjectOriginal, handler);
