import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  ActivityIndicator,
  View,
  Text,
  StyleSheet,
  AppState,
  NativeModules,
  NativeEventEmitter,
  Platform,
} from "react-native";
import { Recording } from "./Components";
import BottomButtons from "./Components/BottomButtons/BottomButtons";
import { AudioModeModel } from "./Components/Model/AudioDevicesModel";
import SwitchToVideoCallModel from "./Components/Model/SwitchToVideoCallModel";
import Participants from "./Components/Participants/Participants";
import { PIPMode } from "./Components/PiPMode/PiPMode";
import Spotlight from "./Components/SpotLight/SpotLight";
import TileMode from "./Components/TileMode/TileMode";
import { useStore } from "./store/Store";
import { color } from "./theme/color";
import Analytics from "./utils/Analytics/Analytics";
import { CALL_TIMEOUT_TIMER_IN_SEC, CALL_TIMEOUT_TYPE, UIMode } from "./utils/Constants";
import { EndCallModel } from "./Components/Model/EndCallModel";
import CallTimeoutModal from "./Components/CallTimeoutModal";
import { CallTimeoutType } from "./Components/CallTimeoutModal/CallTimeoutModal";

let pipModeCallEndTimer = null;

export default function Calling() {
  const { globalState, settings, jitsiManager, nativeManager, room, users } = useStore();
  const [showCallTimeoutModal, setShowCallTimeoutModal] = useState(false);
  const isPipInitialized = useRef(false);

  useLayoutEffect(() => {
    NativeModules.CometChatCommonModule.lockToPortrait();

    return () => {
      NativeModules.CometChatCommonModule.unlockAllOrientations();
    };
  }, []);
  const showCallTimeoutModalTimer = useRef(null);

  useEffect(() => {
    global.ccUsersStats = {};

    if (Platform.OS !== "android") return;
    setTimeout(() => {
      NativeModules.CallNotificationService.startService();
    }, 500);

    NativeModules.PictureInPictureModule.requestAudioFocus();

    NativeModules.PictureInPictureModule.getIsPIPInitialized().then((isInitialized) => {
      isPipInitialized.current = isInitialized;
      if (isInitialized) {
        NativeModules.PictureInPictureModule.setPictureInPictureEnabled(true);
      }
    });

    const pipEventEmitter = new NativeEventEmitter(NativeModules.PictureInPictureModule);

    pipEventEmitter.addListener("onPipModeChanged", (isInPipMode) => {
      if (isInPipMode === false) {
        pipModeCallEndTimer = setTimeout(() => {
          if (isPipInitialized.current && AppState.currentState === "background") {
            jitsiManager.current.leave();
          }
        }, 2000);
      }

      if (isPipInitialized.current && isInPipMode === false) {
        jitsiManager.current.exitPipMode();
      }
    });

    const subscription = AppState.addEventListener("change", (nextAppState) => {
      if (!isPipInitialized.current) return;
      if (nextAppState === "background") {
        jitsiManager.current.enterPipMode();
      } else {
        if (pipModeCallEndTimer) {
          clearTimeout(pipModeCallEndTimer);
          pipModeCallEndTimer = null;
        }
        jitsiManager.current.exitPipMode();
        jitsiManager.current.unMuteVideoProgramatically();
      }
    });

    return () => {
      subscription.remove();
      NativeModules.PictureInPictureModule.setPictureInPictureEnabled(false);
      pipEventEmitter.removeAllListeners("onPipModeChanged");
      NativeModules.CallNotificationService.stopService();
    };
  }, []);

  useEffect(() => {
    if (Platform.OS === "android") {
      const intv = setInterval(() => {
        NativeModules.PictureInPictureModule.isDeviceLocked().then((isLocked) => {
          if (isLocked) {
            jitsiManager.current.muteVideoProgramatically();
          } else {
            jitsiManager.current.unMuteVideoProgramatically();
          }
        });
      }, 5000);
      return () => {
        clearInterval(intv);
      };
    }
    if (Platform.OS !== "ios") return;
    const subscription = AppState.addEventListener("change", (nextAppState) => {
      if (nextAppState === "background") {
        jitsiManager.current.muteVideoWhenInBackground();
      } else {
        jitsiManager.current.unmuteVideoWhenInBackground();
      }
    });

    return () => {
      subscription.remove();
    };
  }, []);

  const startCallTimeoutTimer = () => {
    if (!showCallTimeoutModalTimer.current) {
      showCallTimeoutModalTimer.current = setTimeout(() => {
        setShowCallTimeoutModal(true);
        showCallTimeoutModalTimer.current = null;
      }, settings.idleTimeoutPeriod * 1000 - CALL_TIMEOUT_TIMER_IN_SEC * 1000);
    }
  };

  const endCallTimeoutTimer = () => {
    if (showCallTimeoutModalTimer.current) {
      clearTimeout(showCallTimeoutModalTimer.current);
      showCallTimeoutModalTimer.current = null;
    }
    setShowCallTimeoutModal(false);
  };

  const endCallDueToTimeout = (type: CallTimeoutType) => {
    const uid = users[0]?.uid;
    if (uid && type === CALL_TIMEOUT_TYPE.TIMEOUT_AUTO) {
      room.sendCommandOnce("call-ending-due-to-timeout", {
        attributes: {
          uid: uid,
          idleTimeoutPeriod: settings.idleTimeoutPeriod,
        },
      });
      jitsiManager.current.leave();
      if (nativeManager.current?.onSessionTimeout) nativeManager.current?.onSessionTimeout();
    } else if (type === CALL_TIMEOUT_TYPE.TIMEOUT_CLICK) {
      endCallTimeoutTimer();
      jitsiManager.current.leave();
      if (nativeManager.current?.onCallEndButtonPressed)
        nativeManager.current?.onCallEndButtonPressed();
    } else if (type === CALL_TIMEOUT_TYPE.TIMEOUT_LEAVE) {
      endCallTimeoutTimer();
      if (nativeManager.current?.onCallEndButtonPressed)
        nativeManager.current?.onCallEndButtonPressed();
    }
  };

  useEffect(() => {
    console.log("users", users.length);
    if (users.length === 1) {
      startCallTimeoutTimer();
    } else {
      endCallTimeoutTimer();
    }
  }, [users]);

  useEffect(() => {
    return () => {
      endCallTimeoutTimer();
    };
  }, []);

  const renderCallUI = () => {
    if (globalState.inPIPMode) {
      return <PIPMode />;
    }
    switch (settings.mode) {
      case UIMode.SPOTLIGHT:
        return <Spotlight />;
      case UIMode.TILE:
        return <TileMode />;
      default:
        return <TileMode />;
    }
    return null;
  };
  if (!globalState.conferenceJoined) {
    return (
      <View
        style={{
          flex: 1,
          flexDirection: "row",
          backgroundColor: color.blackLightXX,
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {!globalState.connectionError && <ActivityIndicator size={"small"} color='#fff' />}
        <Text style={{ marginLeft: 10, color: "#fff" }}>
          {globalState.connectionError ? "Couldn't connect, something went wrong!" : "Joining..."}
        </Text>
      </View>
    );
  }
  return (
    <View
      style={globalState.isPortrait ? styles.mainContainerPortrait : styles.mainContainerLandScape}
    >
      <Analytics />
      {renderCallUI()}
      <BottomButtons />
      {globalState.isParticipantsModelVisible ? <Participants /> : null}
      <SwitchToVideoCallModel />
      {globalState.showAudioModel ? <AudioModeModel /> : null}
      {globalState.showEndCallDialog ? <EndCallModel /> : null}
      {globalState.isRecording ? <Recording /> : null}
      {showCallTimeoutModal && (
        <CallTimeoutModal
          onLeave={endCallDueToTimeout}
          onStay={() => {
            setShowCallTimeoutModal(false);
            startCallTimeoutTimer();
          }}
        />
      )}
      {(globalState.noNetwork || globalState.connectionLost) && (
        <View style={[StyleSheet.absoluteFillObject, styles.errorOverlay]}>
          <Text style={styles.errorText}>
            {globalState.noNetwork
              ? "No network connection. Please check your connection."
              : "Connection lost. Trying to reconnect..."}
          </Text>
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  mainContainerPortrait: {
    flex: 1,
    backgroundColor: color.blackLightXX,
    overflow: "hidden",
  },
  mainContainerLandScape: {
    flex: 1,
    backgroundColor: color.blackLightXX,
    flexDirection: "row",
  },
  errorOverlay: {
    backgroundColor: "rgba(0, 0, 0, 0.7)",
    justifyContent: "center",
    alignItems: "center",
    padding: 20,
    zIndex: 1000,
  },
  errorText: {
    color: "#fff",
    fontSize: 16,
    textAlign: "center",
    lineHeight: 24,
  },
});
