import React from "react";
import { View, Text, TouchableOpacity, ActivityIndicator } from "react-native";
import { useStore } from "../../store/Store";
import { SWITCH_TO_REQUEST_MODEL_TYPE } from "../../utils/Constants";
import LOCALIZED_STRING from "../../utils/String";
import style from "./SwitchToVideoCallModel.style";
const SwitchToVideoCallModel = () => {
  const { globalState, jitsiManager }: any = useStore();
  if (!globalState.showSwitchToVideoCallModel) {
    return null;
  }

  const onAccept = () => {
    jitsiManager.current.onSwitchToVideoCallResponse(true);
  };
  const onReject = () => {
    if (globalState.switchToVideoRequestModelType === SWITCH_TO_REQUEST_MODEL_TYPE.INITIAL) {
      jitsiManager.current.onSwitchToVideoCallResponse(false);
    } else {
      jitsiManager.current.leave();
    }
  };
  if (globalState.switchToVideoRequestModelType === SWITCH_TO_REQUEST_MODEL_TYPE.REQUESTED) {
    return (
      <View style={style.model}>
        <ActivityIndicator />
        <Text style={style.headerText}>{LOCALIZED_STRING.SWITCH_TO_VIDEO_CALL_REQUESTED}</Text>
      </View>
    );
  }
  return (
    <View style={style.model}>
      <View style={style.container}>
        <Text style={style.headerText}>
          {globalState.switchToVideoRequestModelType === SWITCH_TO_REQUEST_MODEL_TYPE.INITIAL
            ? `${globalState.switchToVideoCallRequestInitiator.name} ${LOCALIZED_STRING.REQUEST_TO_SWITCH_TO_VIDEO_CALL}`
            : LOCALIZED_STRING.CALL_CONVERTED_TO_VIDEO_CALL}
        </Text>
        <View style={style.buttonContainer}>
          <TouchableOpacity onPress={onAccept} touchSoundDisabled style={style.button}>
            <Text style={style.buttonText}>
              {LOCALIZED_STRING.ACCEPT_REQUEST_TO_SWITCH_TO_VIDEO_CALL}
            </Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={onReject} touchSoundDisabled style={style.button}>
            <Text style={style.buttonText}>
              {globalState.switchToVideoRequestModelType === SWITCH_TO_REQUEST_MODEL_TYPE.INITIAL
                ? LOCALIZED_STRING.REJECT_REQUEST_TO_SWITCH_TO_VIDEO_CALL
                : LOCALIZED_STRING.LEAVE}
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    </View>
  );
};
export default SwitchToVideoCallModel;
