import { IUser } from "../Types/Users";
import { UPDATE_USER_LIST } from "./ActionType";
export interface IUserAction {
  type: string;
  payload?: IUser[];
}
export const userReducer = (state: IUser[], { type, payload }: IUserAction) => {
  console.log("userReducer", type, "payload");
  switch (type) {
    case UPDATE_USER_LIST:
      if (payload) {
        return [...payload];
      } else {
        return state;
      }
    default:
      return { ...state };
  }
};
