import React from "react";
import { TouchableOpacity, Image } from "react-native";
import { ICONS } from "../../icons";

interface IFullScreenButton {
  fullScreen: boolean;
  onButtonPress: () => void;
}

export function FullScreenButton({ onButtonPress, fullScreen }: IFullScreenButton) {
  return (
    <TouchableOpacity
      testID='cc-full-screen'
      touchSoundDisabled
      onPress={onButtonPress}
      style={{ paddingHorizontal: 2 }}
    >
      <Image
        style={{ width: 30, height: 30 }}
        source={fullScreen ? ICONS.FULLSCREEN_DISABLE : ICONS.FULLSCREEN_ENABLE}
      />
    </TouchableOpacity>
  );
}
