import React, { useRef } from "react";
import { TouchableOpacity, Image } from "react-native";
import { useStore } from "../../store/Store";
import style from "./Buttons.styles";
import Logger from "../../utils/Logger";
import { ICONS } from "../../icons";

const TAG = "AudioButton";
export function AudioButton() {
  const { users, jitsiManager } = useStore();
  const prevTime = useRef(0);

  const onButtonPress = () => {
    try {
      const diff = new Date().getTime() - prevTime.current;
      if (diff > 300) {
        Logger.d(TAG, "[onButtonPress]");
        jitsiManager.current.toggleAudioButton();
        prevTime.current = new Date().getTime();
      }
    } catch (error) {
      Logger.d(TAG, "[onButtonPress]", error);
    }
    if (users[0].audioTrack) {
    }
  };
  return (
    <TouchableOpacity
      testID='cc-audio'
      style={style.buttonContainer}
      touchSoundDisabled
      onPress={onButtonPress}
    >
      <Image
        style={style.buttonIcon}
        source={users[0].isAudioMuted ? ICONS.AUDIO_MUTE : ICONS.AUDIO_UNMUTE}
      />
    </TouchableOpacity>
  );
}
