import React from "react";
import { View, Text, TouchableOpacity } from "react-native";
import { useStore } from "../../store/Store";
import style from "./SwitchToVideoCallModel.style";
import Logger from "../../utils/Logger";
import { TOGGLE_END_CALL_DIALOG } from "../../store/ActionType";
const TAG = "EndCallModel";

export const EndCallModel = () => {
  const { jitsiManager, globalRef, nativeManager, dispatch } = useStore();
  const onHangUpCalled = () => {
    try {
      Logger.d(TAG, "[onHangUpCalled]");
      globalRef.current.callEnded = true;
      if (nativeManager.current?.onCallEndButtonPressed)
        nativeManager.current.onCallEndButtonPressed();
    } catch (error) {
      Logger.d(TAG, "[onHangUpCalled]", error);
    }

    try {
      jitsiManager.current.leave();
    } catch (error) {
      Logger.d(TAG, "[onHangUpCalled]", error);
    }
  };

  const endSession = () => {
    dispatch({
      type: TOGGLE_END_CALL_DIALOG,
      payload: false,
    });
    onHangUpCalled();
  };

  const endSessionForAll = () => {
    jitsiManager.current.endSessionForAll();
    dispatch({
      type: TOGGLE_END_CALL_DIALOG,
      payload: false,
    });
    onHangUpCalled();
  };

  return (
    <View style={style.model}>
      <View style={style.container}>
        <Text style={style.headerText}>
          Do you want to end presentation for everyone or just leave the call.
        </Text>
        <View style={style.buttonContainer}>
          <TouchableOpacity onPress={endSessionForAll} touchSoundDisabled style={style.button}>
            <Text style={style.buttonText}>End</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={endSession} touchSoundDisabled style={style.button}>
            <Text style={style.buttonText}>Leave</Text>
          </TouchableOpacity>
        </View>
      </View>
    </View>
  );
};
