import React, { useRef, useEffect, useCallback, useMemo } from "react";
import {
  View,
  Animated,
  PanResponder,
  LayoutAnimation,
  FlatList,
  GestureResponderEvent,
  PanResponderGestureState,
  TouchableWithoutFeedback,
} from "react-native";
import { useStore } from "../../store/Store";
import { AudioButton } from "./AudioButton";
import { AudioModeButton } from "./AudioModeButton";
import style from "./Buttons.styles";
import { EndCallButton } from "./Endcall";
import { RecordingButton } from "./RecordingButton";
import { SwitchCameraButton } from "./SwitchCameraButton";
import SwitchToVideoCallButton from "./SwitchToVideoCallButton";
import { VideoButton } from "./VideoButton";
import { ICONS } from "../../icons";
import { sharedObject } from "../../utils/common";

const bottomSheetHeight = 102;
const NO_OF_COLUMNS = 4;

export default function BottomButtons() {
  const { globalState, settings, users } = useStore();
  const height = globalState.isPortrait
    ? globalState.dimension.height
    : globalState.dimension.width;
  if (globalState.inPIPMode || settings.enableDefaultLayout === false) {
    return null;
  }
  const calcMargin = useMemo(() => {
    return (
      (Math.min(globalState.dimension.height, globalState.dimension.width) - 4 * 60) /
      ((NO_OF_COLUMNS + 3) * 2)
    );
  }, [globalState.dimension.width]);

  useEffect(() => {
    pan.setValue({ x: 0, y: 0 });
    previousValue.setValue(height - bottomSheetHeight);
  }, [globalState.isPortrait, height]);

  const pan: Animated.ValueXY = useRef(new Animated.ValueXY({ x: 0, y: 0 })).current;
  const previousValue = useRef(new Animated.Value(height - bottomSheetHeight)).current;

  const onPanResponderRelease = useCallback(
    (e: GestureResponderEvent, gestureState: PanResponderGestureState) => {
      const newVal = globalState.isPortrait ? gestureState.dy : gestureState.dx;
      LayoutAnimation.configureNext({
        duration: 300,
        create: { type: "linear", property: "opacity" },
        update: { type: "spring", springDamping: 0.4 },
        delete: { type: "linear", property: "opacity" },
      });
      pan.setValue({ x: 0, y: 0 });
      if (newVal > 0) {
        previousValue.setValue(height - bottomSheetHeight);
      } else {
        previousValue.setValue(height - bottomSheetHeight - 70);
      }
    },
    [globalState.isPortrait, pan, height]
  );

  const panResponder = PanResponder.create({
    onStartShouldSetPanResponder: (evt, gestureState) =>
      !(gestureState.dx === 0 && gestureState.dy === 0),
    onPanResponderMove: () =>
      Animated.event(
        [
          null,
          {
            [globalState.isPortrait ? "dy" : "dx"]: pan.y,
          },
        ],
        {
          useNativeDriver: false,
        }
      ),
    onMoveShouldSetPanResponder: (evt, gestureState) => {
      const { dx, dy } = gestureState;
      return dx > 5 || dx < -5 || dy > 5 || dy < -5;
    },
    onPanResponderRelease: onPanResponderRelease,
  });

  const renderPauseVideoButton = () => {
    if (!globalState.conferenceJoined || settings.hidePauseVideoButton || settings.isAudioOnly) {
      return null;
    }
    return <VideoButton />;
  };
  const renderSwitchToVideoCallButton = () => {
    if (
      !globalState.conferenceJoined ||
      !settings.showSwitchToVideoCallButton ||
      !settings.isAudioOnly ||
      users.length - (globalState.noOfScreenShareUser || 0) !== 2
    ) {
      return null;
    }
    return <SwitchToVideoCallButton />;
  };
  const renderAudioPauseButton = () => {
    if (!globalState.conferenceJoined || settings.hideAudioMuteButton) {
      return null;
    }
    return <AudioButton />;
  };
  const renderEndCallButton = () => {
    if (settings.hideEndCallButton) {
      return null;
    }
    return <EndCallButton />;
  };
  const renderCameraSwitchButton = () => {
    if (!globalState.conferenceJoined || settings.hideVideoSwitchButton || settings.isAudioOnly) {
      return null;
    }
    return <SwitchCameraButton />;
  };
  const renderAudioModeButton = () => {
    if (!globalState.conferenceJoined || settings.hideAudioModeButton) {
      return null;
    }
    return <AudioModeButton />;
  };
  const renderRecordButton = () => {
    if (!globalState.conferenceJoined || !settings.showRecordingButton) {
      return null;
    }
    return <RecordingButton />;
  };

  const renderButtons = () => {
    const buttonArr = [];
    const endCall = renderEndCallButton();
    const video = renderPauseVideoButton();
    const audio = renderAudioPauseButton();
    const camSwitch = renderCameraSwitchButton();
    const audioSwitch = renderAudioModeButton();
    const recording = renderRecordButton();
    const switchToVideoCall = renderSwitchToVideoCallButton();
    if (endCall) buttonArr.push(endCall);
    if (audioSwitch) buttonArr.push(audioSwitch);
    if (sharedObject.isPresenter !== false) {
      if (switchToVideoCall) buttonArr.push(switchToVideoCall);
      if (video) buttonArr.push(video);
      if (audio) buttonArr.push(audio);
      if (camSwitch) buttonArr.push(camSwitch);
      if (recording) buttonArr.push(recording);
    }
    return (
      <View
        style={
          globalState.isPortrait
            ? style.buttonListContainerPortrait
            : style.buttonListContainerLandscape
        }
      >
        <FlatList
          key={globalState.isPortrait.toString()}
          scrollEnabled={false}
          contentContainerStyle={
            globalState.isPortrait ? style.buttonListPortrait : style.buttonListLandscape
          }
          showsVerticalScrollIndicator={false}
          numColumns={globalState.isPortrait ? NO_OF_COLUMNS : 1}
          data={buttonArr}
          renderItem={({ item }) => (
            <View
              style={
                globalState.isPortrait
                  ? [
                      style.buttonWrapperPortrait,
                      {
                        marginHorizontal: calcMargin,
                      },
                    ]
                  : [
                      style.buttonWrapperLandscape,
                      {
                        marginVertical: calcMargin,
                      },
                    ]
              }
            >
              {item}
            </View>
          )}
        />
      </View>
    );
  };

  if (globalState.inPIPMode) {
    return null;
  }
  const rotate = Animated.add(previousValue, pan.y).interpolate({
    inputRange: [height - bottomSheetHeight - 70, height - bottomSheetHeight],
    outputRange: globalState.isPortrait ? ["0deg", "180deg"] : ["180deg", "0deg"],
    extrapolate: "clamp",
  });

  return (
    <>
      <View
        style={
          globalState.isPortrait
            ? style.bottomButtonPlaceHolderPortrait
            : style.bottomButtonPlaceHolderLandscape
        }
      ></View>
      <Animated.View
        {...panResponder.panHandlers}
        style={
          globalState.isPortrait
            ? [
                style.bottomButtonContainerPortrait,
                {
                  top: Animated.add(
                    previousValue,
                    pan.y.interpolate({
                      inputRange: [-1000, 0, 1000],
                      outputRange: [-1000, 0, 1000],
                      extrapolate: "clamp",
                    })
                  ),
                },
              ]
            : [
                style.bottomButtonContainerLandscape,
                {
                  left: Animated.add(
                    previousValue,
                    pan.y.interpolate({
                      inputRange: [-1000, 0, 1000],
                      outputRange: [-1000, 0, 1000],
                      extrapolate: "clamp",
                    })
                  ),
                },
              ]
        }
      >
        <TouchableWithoutFeedback>
          <View
            style={
              globalState.isPortrait
                ? style.touchableContainerPortrait
                : style.touchableContainerLandScape
            }
          >
            <View
              style={
                globalState.isPortrait
                  ? style.bottomArrowContainerPortrait
                  : style.bottomArrowContainerLandScape
              }
            >
              <Animated.Image
                style={[
                  style.bottomButtonArrow,
                  {
                    transform: [
                      globalState.isPortrait ? { rotateX: rotate } : { rotateY: rotate },
                      { rotate: globalState.isPortrait ? "0deg" : "90deg" },
                    ],
                  },
                ]}
                resizeMode={"stretch"}
                source={ICONS.ARROW}
              ></Animated.Image>
            </View>
            {renderButtons()}
          </View>
        </TouchableWithoutFeedback>
      </Animated.View>
    </>
  );
}
