import React, { useCallback } from "react";
import { NativeModules, TouchableOpacity, View, Image, StyleSheet } from "react-native";
import { useStore } from "../../store/Store";
import { ICONS } from "../../icons";
import { IAudioMode } from "../../store/GlobalState.types";
import { color } from "../../theme/color";
import { AUDIO_MODE_TYPE } from "../../utils/Constants";
import RadioButtonRN from "../../utils/RadioButton";
import { TOGGLE_AUDIO_MODE_MODEL } from "../../store/ActionType";

const { AudioMode } = NativeModules;
export default AudioMode;

export function AudioModeModel() {
  const { globalState, dispatch } = useStore();

  const renderIcon = (selectedDevice: keyof typeof AUDIO_MODE_TYPE) => {
    switch (selectedDevice) {
      case AUDIO_MODE_TYPE.SPEAKER:
        return renderSpeakerIcon();
      case AUDIO_MODE_TYPE.BLUETOOTH:
        return renderBluetoothIcon();
      case AUDIO_MODE_TYPE.HEADPHONES:
        return renderHeadphoneIcon();
      case AUDIO_MODE_TYPE.EARPIECE:
        return renderEarPieceIcon();
      default:
        return renderSpeakerIcon();
    }
  };

  const renderSpeakerIcon = () => {
    return <Image style={style.lt_control_icon} source={ICONS.AUDIO_MODE_SPEAKER} />;
  };

  const renderEarPieceIcon = () => {
    return <Image style={style.lt_control_icon} source={ICONS.AUDIO_MODE_EARPIECE} />;
  };

  const renderHeadphoneIcon = () => {
    return <Image style={style.lt_control_icon} source={ICONS.AUDIO_MODE_HEADPHONE} />;
  };

  const renderBluetoothIcon = () => {
    return <Image style={style.lt_control_icon} source={ICONS.AUDIO_MODE_BLUETOOTH} />;
  };

  const onBackDropPress = () => {
    dispatch({
      type: TOGGLE_AUDIO_MODE_MODEL,
      payload: false,
    });
  };

  const onSelect = (item: IAudioMode) => {
    onBackDropPress();
    AudioMode.setAudioDevice(item.uid || item.type);
  };

  const loadAudioList = useCallback(() => {
    return (
      <RadioButtonRN data={globalState.audioModes} renderIcon={renderIcon} selectedBtn={onSelect} />
    );
  }, [globalState.audioModes]);

  return (
    <TouchableOpacity onPress={onBackDropPress} style={style.container}>
      <View style={style.listContainer}>{loadAudioList()}</View>
    </TouchableOpacity>
  );
}
const style = StyleSheet.create({
  lt_control_icon: { width: 25, height: 25 },
  lt_control_view: {
    width: 55,
    height: 55,
    margin: 1,
    backgroundColor: color.lightGrey,
    borderRadius: 50,
    alignItems: "center",
    justifyContent: "center",
  },
  container: {
    position: "absolute",
    top: 0,
    bottom: 0,
    right: 0,
    left: 0,
    backgroundColor: color.blackTransparent,
    elevation: 10,
    justifyContent: "flex-end",
    alignItems: "center",
  },
  listContainer: {
    backgroundColor: color.blackLight,
    padding: 10,
    borderTopEndRadius: 8,
    borderTopStartRadius: 8,
    width: "100%",
  },
});
