import React, { useRef } from "react";
import { useEffect, forwardRef, useImperativeHandle } from "react";
import { ColorValue, View } from "react-native";
import Calling from "./Calling";
import { NativeManager } from "./NativeManager/NativeManager";

import { Context, ContextProvider } from "./store/Store";
import Logger from "./utils/Logger";
// import { LogBox } from "react-native";
import "./Polyfill";
import JitsiManger from "./JitsiManager/JitsiManager";
import { reducer } from "./store/GlobalReducer";
import { SET_DIMENSION } from "./store/ActionType";
import { color } from "./theme/color";
import { sharedObject } from "./utils/common";
import { CALL_TIMEOUT_DEFAULT_IN_SEC, CALL_TIMEOUT_MIN_IN_SEC } from "./utils/Constants";
((global: any) => {
  if (typeof global.$ === "undefined") {
    const jQuery = require("jquery");
    jQuery(global);
    global.$ = jQuery;
  }
})(global || window);
// LogBox.ignoreLogs(["new NativeEventEmitter"]); // Ignore log notification by message
// LogBox.ignoreAllLogs();
const TAG = "index.js";
const dimension = { width: 0, height: 0 };
const pipDimension = { width: 0, height: 0 };
const App = forwardRef(function App(props: Props, ref: any) {
  console.log("video Settings are here ", props.mainVideoSetting);
  sharedObject.isPresenter = props.isPresenter;
  sharedObject.mode = props.mode;

  const defaultSettings = {
    enableVideoTileClick: props.enableVideoTileClick ?? true,
    enableDraggableVideoTile: props.enableDraggableVideoTile ?? true,
  };
  const videoSettings = {
    videoFit: props.mainVideoSetting?.videoFit ?? "contain",
    fullScreenButton: {
      visibility: props.mainVideoSetting?.fullScreenButton?.visibility ?? true,
      position: props.mainVideoSetting?.fullScreenButton?.position ?? "bottom-right",
    },
    userListButton: {
      visibility: props.mainVideoSetting?.userListButton?.visibility ?? true,
      position: props.mainVideoSetting?.userListButton?.position ?? "bottom-right",
    },
    zoomButton: {
      visibility: props.mainVideoSetting?.zoomButton?.visibility ?? true,
      position: props.mainVideoSetting?.zoomButton?.position ?? "bottom-right",
    },
    nameLabel: {
      visibility: props.mainVideoSetting?.nameLabel?.visibility ?? true,
      position: props.mainVideoSetting?.nameLabel?.position ?? "bottom-left",
      color: props.mainVideoSetting?.nameLabel?.color ?? color.blackLightXX,
    },
  };
  const externalFunRef = useRef<ExternalFunType | null>();
  const externalNativeFunRef = useRef<any | null>();
  useImperativeHandle(ref, () => ({
    muteAudio: () => externalFunRef.current?.muteAudio(),
    unMuteAudio: () => externalFunRef.current?.unMuteAudio(),
    switchCamera: () => externalFunRef.current?.flipCamera(),
    pauseVideo: () => externalFunRef.current?.muteVideo(),
    unPauseVideo: () => externalFunRef.current?.unMuteVideo(),
    endCall: () => externalFunRef.current?.leave(),
    switchToVideoCall: () => externalFunRef.current?.requestingToSwitchToVideoCall(),
    startRecording: () => externalFunRef.current?.startRecording(),
    stopRecording: () => externalFunRef.current?.stopRecording(),
    toggleAudioButton: () => externalFunRef.current?.toggleAudioButton(), // Not available in sdk
    toggleVideoButton: () => externalFunRef.current?.toggleVideoButton(), // Not available in sdk
    enterPipMode: () => externalFunRef.current?.enterPipMode(), // Not available in sdk
    exitPipMode: () => externalFunRef.current?.exitPipMode(), // Not available in sdk
    setAudioMode: (mode: IModes) => externalNativeFunRef.current?.setAudioMode(mode),
    getAudioModes: () => externalNativeFunRef.current?.getAudioModes(),
  }));
  useEffect(() => {
    Logger.d(TAG, "[index.js] [useEffect]");

    // jitsiManagerRef.current?.initialize();
  }, []);

  return (
    <ContextProvider
      reducer={reducer}
      initialState={{
        ...props,
        ...defaultSettings,
        videoSettings,
        idleTimeoutPeriod:
          typeof props.idleTimeoutPeriod === "number"
            ? Math.max(props.idleTimeoutPeriod, CALL_TIMEOUT_MIN_IN_SEC)
            : CALL_TIMEOUT_DEFAULT_IN_SEC,
      }}
    >
      <Context.Consumer>
        {(storeValue) => (
          <View
            onLayout={(event: any) => {
              console.log(event.nativeEvent, pipDimension, dimension);
              if (pipDimension.height === 0 && storeValue.globalState.inPIPMode) {
                pipDimension.width = event.nativeEvent.layout.width;
                pipDimension.height = event.nativeEvent.layout.height;
              }
              if (dimension.height === 0 && !storeValue.globalState.inPIPMode) {
                dimension.width = event.nativeEvent.layout.width;
                dimension.height = event.nativeEvent.layout.height;
              }
              storeValue?.dispatch({
                type: SET_DIMENSION,
                payload: event.nativeEvent.layout,
              });
            }}
            // TODO : Is the background red required ??
            style={[
              { backgroundColor: color.palette.red },
              dimension.height !== 0 && !storeValue.globalState.inPIPMode
                ? { width: dimension.width, height: dimension.height }
                : storeValue.globalState.inPIPMode && pipDimension.height !== 0
                ? { width: pipDimension.width, height: pipDimension.height }
                : { flex: 1 },
            ]}
          >
            <JitsiManger
              ref={(ref) => {
                storeValue.jitsiManager.current = ref;
                externalFunRef.current = ref;
              }}
            />
            <NativeManager
              ref={(ref) => {
                storeValue.nativeManager.current = ref;
                externalNativeFunRef.current = ref;
              }}
              {...storeValue.settings}
            />

            <Calling />
          </View>
        )}
      </Context.Consumer>
    </ContextProvider>
  );
});
type ExternalFunType = {
  requestingToSwitchToVideoCall: Function;
  muteAudio: Function;
  unMuteAudio: Function;
  flipCamera: Function;
  muteVideo: Function;
  unMuteVideo: Function;
  leave: Function;
  switchToVideoCall: Function;
  startRecording: Function;
  stopRecording: Function;
  toggleAudioButton: Function;
  toggleVideoButton: Function;
  enterPipMode: Function;
  exitPipMode: Function;
};
export type Props = {
  hideAudioModeButton: boolean;
  hideAudioMuteButton: boolean;
  showRecordingButton: boolean;
  idleTimeoutPeriod: number;
  isInitiator: boolean;
  sessionId: string;
  hideEndCallButton: boolean;
  isConference: boolean;
  defaultAudioMode: string;
  avatarMode: string;
  startVideoMuted: boolean;
  enableDefaultLayout: boolean;
  isSingleMode: boolean;
  domain: string;
  isAudioOnly: boolean;
  isPresenter: boolean;
  showSwitchToVideoCallButton: boolean;
  REGION: string;
  startRecordingOnCallStart: boolean;
  startAudioMuted: boolean;
  mode: string;
  hidePauseVideoButton: boolean;
  analyticsSettings: {
    ANALYTICS_HOST: string;
    ANALYTICS_VERSION: string;
    ANALYTICS_PING_DISABLED: boolean;
    ANALYTICS_USE_SSL: boolean;
  };
  enableVideoTileClick: Boolean;
  enableDraggableVideoTile: Boolean;
  mainVideoSetting: {
    videoFit: "contain" | "cover" | "default";
    fullScreenButton: {
      visibility: boolean;
      position: "top-right" | "bottom-right" | "top-left" | "bottom-left";
    };
    userListButton: {
      visibility: boolean;
      position: "top-right" | "bottom-right" | "top-left" | "bottom-left";
    };
    zoomButton: {
      visibility: boolean;
      position: "top-right" | "bottom-right" | "top-left" | "bottom-left";
    };
    nameLabel: {
      visibility: boolean;
      position: "top-right" | "bottom-right" | "top-left" | "bottom-left";
      color: ColorValue;
    };
  };
  hideVideoSwitchButton: boolean;
  appId: string;
  RTCUser: {
    name: string;
    resource: string;
    avatar: string;
    uid: string;
  };
};
export type IModes = "BLUETOOTH" | "EARPIECE" | "SPEAKER" | "HEADPHONES";

export default App;
