import React from "react";
import { TouchableOpacity, Image } from "react-native";
import { ICONS } from "../../icons";

interface IZoomButton {
  videoFit: "cover" | "contain" | "default";
  onButtonPress: () => void;
}

export function ZoomButton({ onButtonPress, videoFit }: IZoomButton) {
  return (
    <TouchableOpacity
      testID='cc-zoom'
      touchSoundDisabled
      onPress={onButtonPress}
      style={{ paddingHorizontal: 2 }}
    >
      <Image
        style={{ width: 25, height: 25 }}
        source={videoFit === "cover" ? ICONS.ZOOM_OUT : ICONS.ZOOM_IN}
      />
    </TouchableOpacity>
  );
}
